function escapeHtml(text) {
  return text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
}

from pathlib import Path

def has_extension(path: Path, extension: str) -> bool:
    return path.suffix.casefold() == extension.casefold()

def alternate(items):
    for index, item in enumerate(items):
        if index % 2 == 0:
            yield item

def common_prefix(strings):
    iterator = iter(strings)
    try:
        prefix = next(iterator)
    except StopIteration:
        return ""
    for string in iterator:
        while not string.startswith(prefix):
            prefix = prefix[:-1]
    return prefix

def index_positions(items):
    result = {}
    for index, item in enumerate(items):
        result.setdefault(item, []).append(index)
    return result

def pad_left(text: str, width: int, fill: str = " ") -> str:
    if width < 0 or len(fill) != 1:
        raise ValueError("invalid padding")
    return fill * max(0, width - len(text)) + text

export function sumSquares(values: readonly number[]): number {
  let total = 0;
  for (const value of values) {
    if (Number.isFinite(value)) total += value * value;
  }
  return total;
}

function countSubstring(text, needle) {
  if (needle === "") throw new Error("empty needle");
  let count = 0;
  let position = 0;
  while (true) {
    const found = text.indexOf(needle, position);
    if (found < 0) return count;
    count++;
    position = found + needle.length;
  }
}

export function omitKey<T extends object, K extends keyof T>(value: T, key: K): Omit<T, K> {
  const { [key]: ignored, ...rest } = value;
  return rest as Omit<T, K>;
}

static boolean isUpperAscii(char ch) {
    return ch >= 'A' && ch <= 'Z';
}

static String removeWhitespaceEdges(String text) {
    int start = 0;
    int end = text.length();
    while (start < end && Character.isWhitespace(text.charAt(start))) start++;
    while (end > start && Character.isWhitespace(text.charAt(end - 1))) end--;
    return text.substring(start, end);
}

from solution import overlap_count

def test_disjoint():
    assert overlap_count({1, 2}, {3}) == 0

def test_identical():
    assert overlap_count({1, 2}, {1, 2}) == 2

def test_partial_and_inputs_unchanged():
    left, right = {1, 2, 3}, {2, 3, 4}
    assert overlap_count(left, right) == 2
    assert left == {1, 2, 3}
    assert right == {2, 3, 4}
